const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Function to mask clouds and shadows in Landsat 4, 5, 7
function maskL457(image) {
  const qa = image.select('QA_PIXEL');
  // Bits 3 and 5 are cloud shadow and cloud, respectively.
  const cloudShadowBitMask = (1 << 3);
  const cloudsBitMask = (1 << 5);
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
  return image.updateMask(mask);
}

// Function to mask clouds and shadows in Landsat 8/9
function maskL89(image) {
  const qa = image.select('QA_PIXEL');
  // Bits 3 and 5 are cloud shadow and cloud, respectively.
  const cloudShadowBitMask = (1 << 3);
  const cloudsBitMask = (1 << 5);
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
  return image.updateMask(mask);
}

// Function to calculate NDVI
function addNDVI(image) {
    // Standardize band names for NDVI calculation
    const nir = image.select('.*_nir');
    const red = image.select('.*_red');
    const ndvi = nir.subtract(red).divide(nir.add(red)).rename('ndvi');
    return image.addBands(ndvi);
}

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Point([30.428, 31.417]).buffer(5000); // Rosetta mouth, 5km buffer
    const year1_start = '1984-06-01';
    const year1_end = '1984-08-31';
    const year2_start = '2021-06-01';
    const year2_end = '2021-08-31';

    // 2. Data Acquisition & Check
    const l5_bands = ['B3', 'B4', 'QA_PIXEL'];
    const l5_names = ['red', 'nir', 'QA_PIXEL'];
    const col1984_raw = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(geometry)
        .filterDate(year1_start, year1_end)
        .select(l5_bands, l5_names);

    const l8_bands = ['SR_B4', 'SR_B5', 'QA_PIXEL'];
    const l8_names = ['red', 'nir', 'QA_PIXEL'];
    const col2021_raw = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(geometry)
        .filterDate(year2_start, year2_end)
        .select(l8_bands, l8_names);

    const size1984 = col1984_raw.size().getInfo();
    const size2021 = col2021_raw.size().getInfo();

    if (size1984 === 0 || size2021 === 0) {
        console.log(`Image count 1984: ${size1984}`);
        console.log(`Image count 2021: ${size2021}`);
        console.log('No images found for one or both periods.');
        console.log('C1');
        return;
    }
    console.log(`Image count 1984: ${size1984}`);
    console.log(`Image count 2021: ${size2021}`);

    // 3. Processing
    const image1984 = col1984_raw.map(maskL457).map(addNDVI).median();
    const image2021 = col2021_raw.map(maskL89).map(addNDVI).median();

    // Mask for vegetation (NDVI > 0.1) to exclude water/barren land
    const vegMask1984 = image1984.select('ndvi').gt(0.1);
    const vegMask2021 = image2021.select('ndvi').gt(0.1);

    const image1984_veg = image1984.updateMask(vegMask1984);
    const image2021_veg = image2021.updateMask(vegMask2021);

    const reduce_args = {
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: geometry,
        scale: 1000,
        maxPixels: 1e9
    };

    const stats1984 = image1984_veg.reduceRegion(reduce_args);
    const stats2021 = image2021_veg.reduceRegion(reduce_args);

    const mean1984 = stats1984.get('ndvi_mean').getInfo();
    const count1984 = stats1984.get('ndvi_count').getInfo();
    const mean2021 = stats2021.get('ndvi_mean').getInfo();
    const count2021 = stats2021.get('ndvi_count').getInfo();

    // 4. Validation
    if (count1984 === 0 || count2021 === 0) {
        console.log(`Valid pixel count 1984: ${count1984}`);
        console.log(`Valid pixel count 2021: ${count2021}`);
        console.log('No valid pixels after cloud and water masking.');
        console.log('C2');
        return;
    }

    if (mean1984 === null || mean2021 === null) {
        console.log(`Mean NDVI 1984: ${mean1984}`);
        console.log(`Mean NDVI 2021: ${mean2021}`);
        console.log('Calculation resulted in null.');
        console.log('C3');
        return;
    }

    // 5. Final Answer
    console.log(`1984 Mean NDVI: ${mean1984.toFixed(4)} (Pixels: ${count1984})`);
    console.log(`2021 Mean NDVI: ${mean2021.toFixed(4)} (Pixels: ${count2021})`);

    if (mean1984 > mean2021) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(e);
    console.log('D');
});
